-- 0059 — CAT : catalogue de référence des véhicules (marques, modèles, variantes) et sa graine.
-- US-113 ; 16 HST-050 ; 17 §3.2.3 (`vehicle_make`, `vehicle_model`, `vehicle_variant`), ADR-034 ;
-- 22 OQ-CAT-01 ; ADR-094. Appliquée sous `migrator`, en une transaction.
--
-- Principes (ADR-094) :
--   - catalogue MAISON, commun aux pays (colonne `market` : pays de la variante, NULL = tous) ;
--     aucune donnée aspirée ni copiée d'un tiers (Turo, annonces, sites de constructeurs) ;
--   - chaque ligne porte `source` et `license_note` NON VIDES (NOT NULL + CHECK) : une ligne de
--     graine sans licence fait échouer la migration, qui n'est qu'une transaction, et rien n'est
--     chargé (19 US-113 critère 1 ; preuve : test-migrations/9970_test_us113_catalog_fixtures.sql) ;
--   - une source dont la licence n'est pas validée (OQ-CAT-01 a, b) ne peut pas être rendue :
--     la graine ci-dessous est GÉNÉRÉE depuis apps/api/src/modules/cat/data/vehicle-catalog.json
--     par apps/api/src/modules/cat/internal/vehicle-catalog/seed-sql.ts, qui refuse ces sources
--     (`CATALOG_SOURCE_UNLICENSED`) ; le test seed-sql.test.ts compare la section au rendu ;
--   - une consommation EPA est une valeur US indicative (`EPA_US_REFERENCE`), toujours étiquetée
--     « référence US » à l'affichage ; la graine n'en contient aucune tant qu'OQ-CAT-01 (b) est
--     ouverte ; valeur et source vont ensemble (CHECK) ;
--   - classe de suppression D : retrait par `status = 'RETIRED'`, jamais de DELETE ni de TRUNCATE
--     (garde, tous rôles, migrator compris) ;
--   - lecture publique des noms et caractéristiques par `app_api` (lignes ACTIVE et RETIRED, sans
--     provenance ni vérificateur) ; app_worker et app_anon : rien ; aucune écriture applicative
--     (bêta : graine par migration, file d'ajout US-114).
--
-- Retour arrière (base sans dépendance ; US-115 y rattachera `vehicle.variant_id`) :
--   DROP TABLE core.catalog_vehicle_variant, core.catalog_vehicle_model, core.catalog_vehicle_make;
--   DROP FUNCTION core.catalog_vehicle_no_delete().

-- 1. Tables (17 §3.2.3) -------------------------------------------------------------------------
CREATE TABLE core.catalog_vehicle_make (
  id             uuid        PRIMARY KEY,
  slug           text        NOT NULL UNIQUE CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  name           text        NOT NULL CHECK (btrim(name) <> '' AND length(name) <= 80),
  country_origin char(2)     CHECK (country_origin ~ '^[A-Z]{2}$'),
  aliases        text[]      NOT NULL DEFAULT ARRAY[]::text[],
  status         text        NOT NULL DEFAULT 'ACTIVE'
                             CHECK (status IN ('ACTIVE', 'PENDING_REVIEW', 'RETIRED')),
  source         text        NOT NULL
                             CHECK (source IN ('WIKIDATA', 'NHTSA_VPIC', 'OPS_CURATED', 'HOST_REQUEST')),
  source_ref     text        CHECK (source_ref IS NULL OR btrim(source_ref) <> ''),
  license_note   text        NOT NULL CHECK (btrim(license_note) <> '' AND length(license_note) <= 500),
  created_at     timestamptz NOT NULL DEFAULT platform.now()
);
COMMENT ON TABLE core.catalog_vehicle_make IS
  'CAT vehicle_make (17 §3.2.3, ADR-034) : marque du catalogue de référence ; source et '
  'license_note obligatoires ; retrait par RETIRED. US-113.';

CREATE TABLE core.catalog_vehicle_model (
  id             uuid        PRIMARY KEY,
  make_id        uuid        NOT NULL REFERENCES core.catalog_vehicle_make (id),
  slug           text        NOT NULL CHECK (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  name           text        NOT NULL CHECK (btrim(name) <> '' AND length(name) <= 80),
  aliases        text[]      NOT NULL DEFAULT ARRAY[]::text[],
  body_type      text        NOT NULL
                             CHECK (body_type IN ('SUV', 'PICKUP', 'SEDAN', 'HATCHBACK', 'VAN',
                                                  'MINIVAN', 'COUPE', 'CONVERTIBLE', 'WAGON')),
  seats_default  smallint    NOT NULL CHECK (seats_default BETWEEN 1 AND 60),
  doors_default  smallint    NOT NULL CHECK (doors_default BETWEEN 1 AND 6),
  status         text        NOT NULL DEFAULT 'ACTIVE'
                             CHECK (status IN ('ACTIVE', 'PENDING_REVIEW', 'RETIRED')),
  source         text        NOT NULL
                             CHECK (source IN ('WIKIDATA', 'NHTSA_VPIC', 'OPS_CURATED', 'HOST_REQUEST')),
  source_ref     text        CHECK (source_ref IS NULL OR btrim(source_ref) <> ''),
  license_note   text        NOT NULL CHECK (btrim(license_note) <> '' AND length(license_note) <= 500),
  created_at     timestamptz NOT NULL DEFAULT platform.now(),
  CONSTRAINT catalog_vehicle_model_make_slug_key UNIQUE (make_id, slug)
);
COMMENT ON TABLE core.catalog_vehicle_model IS
  'CAT vehicle_model (17 §3.2.3, ADR-034) : modèle d''une marque ; source et license_note '
  'obligatoires ; retrait par RETIRED. US-113.';

CREATE TABLE core.catalog_vehicle_variant (
  id                  uuid         PRIMARY KEY,
  model_id            uuid         NOT NULL REFERENCES core.catalog_vehicle_model (id),
  year_from           integer      NOT NULL CHECK (year_from BETWEEN 1950 AND 2100),
  year_to             integer      CHECK (year_to IS NULL OR year_to >= year_from),
  trim_name           text         CHECK (trim_name IS NULL OR (btrim(trim_name) <> ''
                                                                AND length(trim_name) <= 80)),
  transmission        text         NOT NULL CHECK (transmission IN ('MT', 'AT', 'CVT', 'DCT')),
  fuel_type           text         NOT NULL
                                   CHECK (fuel_type IN ('GASOLINE', 'DIESEL', 'HYBRID', 'PHEV', 'EV', 'LPG')),
  drive               text         NOT NULL CHECK (drive IN ('FWD', 'RWD', 'AWD', '4X4')),
  engine_cc           integer      CHECK (engine_cc BETWEEN 50 AND 10000),
  engine_cylinders    smallint     CHECK (engine_cylinders BETWEEN 1 AND 16),
  power_hp            integer      CHECK (power_hp BETWEEN 1 AND 2000),
  consumption_l_100km numeric(3,1) CHECK (consumption_l_100km > 0),
  consumption_source  text         CHECK (consumption_source IN ('EPA_US_REFERENCE', 'OPS_CURATED')),
  seats               smallint     NOT NULL CHECK (seats BETWEEN 1 AND 60),
  doors               smallint     NOT NULL CHECK (doors BETWEEN 1 AND 6),
  cargo_l             integer      CHECK (cargo_l BETWEEN 1 AND 20000),
  value_class         text         CHECK (value_class IN ('STANDARD', 'PREMIUM', 'LUXE')),
  market              char(2)      REFERENCES core.config_country (code),
  status              text         NOT NULL DEFAULT 'ACTIVE'
                                   CHECK (status IN ('ACTIVE', 'PENDING_REVIEW', 'RETIRED')),
  source              text         NOT NULL
                                   CHECK (source IN ('WIKIDATA', 'NHTSA_VPIC', 'OPS_CURATED', 'HOST_REQUEST')),
  source_ref          text         CHECK (source_ref IS NULL OR btrim(source_ref) <> ''),
  license_note        text         NOT NULL
                                   CHECK (btrim(license_note) <> '' AND length(license_note) <= 500),
  verified_by         uuid         REFERENCES core.iam_user_account (id),
  verified_at         timestamptz,
  created_at          timestamptz  NOT NULL DEFAULT platform.now(),
  -- une consommation n'existe jamais sans sa source (EPA = « référence US », 17 §3.2.3)
  CONSTRAINT catalog_vehicle_variant_consumption_sourced
    CHECK ((consumption_l_100km IS NULL) = (consumption_source IS NULL)),
  CONSTRAINT catalog_vehicle_variant_verified_pair
    CHECK ((verified_by IS NULL) = (verified_at IS NULL)),
  CONSTRAINT catalog_vehicle_variant_natural_key
    UNIQUE NULLS NOT DISTINCT (model_id, year_from, trim_name, transmission, fuel_type, drive, market)
);
COMMENT ON TABLE core.catalog_vehicle_variant IS
  'CAT vehicle_variant (17 §3.2.3, ADR-034) : variante (années, finition, boîte, carburant, '
  'transmission) qui préremplit le véhicule de l''hôte ; source et license_note obligatoires ; '
  'consommation EPA étiquetée « référence US » ; retrait par RETIRED. US-113.';

CREATE INDEX catalog_vehicle_variant_model_idx ON core.catalog_vehicle_variant (model_id, year_from);

-- 2. Garde : jamais de DELETE ni de TRUNCATE (classe D, retrait par RETIRED ; tous rôles) -------
CREATE FUNCTION core.catalog_vehicle_no_delete()
  RETURNS trigger
  LANGUAGE plpgsql
  SET search_path = pg_catalog, pg_temp
AS $fn$
BEGIN
  RAISE EXCEPTION '%: % refused (retire with status RETIRED)', TG_TABLE_NAME, TG_OP
    USING ERRCODE = 'integrity_constraint_violation', CONSTRAINT = 'catalog_vehicle_retire_only';
END
$fn$;
REVOKE ALL ON FUNCTION core.catalog_vehicle_no_delete() FROM PUBLIC;

CREATE TRIGGER catalog_vehicle_make_no_delete
  BEFORE DELETE ON core.catalog_vehicle_make
  FOR EACH ROW EXECUTE FUNCTION core.catalog_vehicle_no_delete();
CREATE TRIGGER catalog_vehicle_make_no_truncate
  BEFORE TRUNCATE ON core.catalog_vehicle_make
  FOR EACH STATEMENT EXECUTE FUNCTION core.catalog_vehicle_no_delete();
CREATE TRIGGER catalog_vehicle_model_no_delete
  BEFORE DELETE ON core.catalog_vehicle_model
  FOR EACH ROW EXECUTE FUNCTION core.catalog_vehicle_no_delete();
CREATE TRIGGER catalog_vehicle_model_no_truncate
  BEFORE TRUNCATE ON core.catalog_vehicle_model
  FOR EACH STATEMENT EXECUTE FUNCTION core.catalog_vehicle_no_delete();
CREATE TRIGGER catalog_vehicle_variant_no_delete
  BEFORE DELETE ON core.catalog_vehicle_variant
  FOR EACH ROW EXECUTE FUNCTION core.catalog_vehicle_no_delete();
CREATE TRIGGER catalog_vehicle_variant_no_truncate
  BEFORE TRUNCATE ON core.catalog_vehicle_variant
  FOR EACH STATEMENT EXECUTE FUNCTION core.catalog_vehicle_no_delete();

-- 3. RLS : ENABLE + FORCE, migrator_all ; lecture publique d'app_api ; aucune écriture ----------
ALTER TABLE core.catalog_vehicle_make ENABLE ROW LEVEL SECURITY;
ALTER TABLE core.catalog_vehicle_make FORCE ROW LEVEL SECURITY;
ALTER TABLE core.catalog_vehicle_model ENABLE ROW LEVEL SECURITY;
ALTER TABLE core.catalog_vehicle_model FORCE ROW LEVEL SECURITY;
ALTER TABLE core.catalog_vehicle_variant ENABLE ROW LEVEL SECURITY;
ALTER TABLE core.catalog_vehicle_variant FORCE ROW LEVEL SECURITY;
CREATE POLICY migrator_all ON core.catalog_vehicle_make TO migrator USING (true) WITH CHECK (true);
CREATE POLICY migrator_all ON core.catalog_vehicle_model TO migrator USING (true) WITH CHECK (true);
CREATE POLICY migrator_all ON core.catalog_vehicle_variant TO migrator USING (true) WITH CHECK (true);
REVOKE ALL ON core.catalog_vehicle_make, core.catalog_vehicle_model, core.catalog_vehicle_variant
  FROM PUBLIC;

-- Lecture publique (16 HST-050 « lecture publique des noms et caractéristiques ») : lignes ACTIVE
-- (choix de l'assistant) et RETIRED (refus CATALOG_VARIANT_RETIRED d'une variante déjà choisie) ;
-- PENDING_REVIEW reste à l'ops (US-114). Ni provenance (source, source_ref, license_note), ni
-- vérificateur (verified_by, verified_at), ni horodatage de création.
GRANT SELECT (id, slug, name, country_origin, aliases, status)
  ON core.catalog_vehicle_make TO app_api;
CREATE POLICY api_read ON core.catalog_vehicle_make FOR SELECT TO app_api
  USING (status IN ('ACTIVE', 'RETIRED'));
GRANT SELECT (id, make_id, slug, name, aliases, body_type, seats_default, doors_default, status)
  ON core.catalog_vehicle_model TO app_api;
CREATE POLICY api_read ON core.catalog_vehicle_model FOR SELECT TO app_api
  USING (status IN ('ACTIVE', 'RETIRED'));
GRANT SELECT (id, model_id, year_from, year_to, trim_name, transmission, fuel_type, drive, engine_cc,
              engine_cylinders, power_hp, consumption_l_100km, consumption_source, seats, doors,
              cargo_l, value_class, market, status)
  ON core.catalog_vehicle_variant TO app_api;
CREATE POLICY api_read ON core.catalog_vehicle_variant FOR SELECT TO app_api
  USING (status IN ('ACTIVE', 'RETIRED'));

